/**
 * Moves keyboard focus to a part and reads where it is. On iOS and Android it
 * moves a screen reader's focus too, which cannot be read back, so restoring it
 * there is a best effort.
 */
export interface Focus<N> {
  /**
   * Moves focus to `node`. With `preventScroll`, nothing scrolls to show it.
   */
  readonly focus: (node: N, preventScroll: boolean) => void

  /** The part with keyboard focus, or `null` where none has it. */
  readonly focused: () => N | null
}
